package org.sleepwell.app;
import android.content.ContentValues;import org.json.*;import java.util.*;
/** Format eight preserves frozen policy, immutable evidence and reversible review outcomes. */
final class AwakeBackup {
 static void export(Store store,JSONObject root)throws JSONException{root.put("awake_runs",new JSONArray(store.rows("SELECT * FROM awake_runs")));root.put("awake_estimates",new JSONArray(store.rows("SELECT * FROM awake_estimates")));validate(root);}
 static void validate(JSONObject root)throws JSONException{
  Map<Long,JSONObject> sessions=new HashMap<>(),runs=new HashMap<>();JSONArray ss=root.getJSONArray("sessions"),rr=root.getJSONArray("awake_runs"),ee=root.getJSONArray("awake_estimates");if(rr.length()>100000||ee.length()>100000)throw new JSONException("Too much awake evidence");for(int n=0;n<ss.length();n++){JSONObject s=ss.getJSONObject(n);sessions.put(SensorProvenance.whole(s,"id"),s);}
  for(int n=0;n<rr.length();n++){JSONObject r=rr.getJSONObject(n);long id=SensorProvenance.whole(r,"session"),revision=SensorProvenance.whole(r,"revision");JSONObject session=sessions.get(id);String policy=SensorProvenance.text(r,"policy"),state=SensorProvenance.text(r,"state"),error=SensorProvenance.text(r,"error");AwakePolicy p;try{p=AwakePolicy.decode(policy);}catch(IllegalArgumentException bad){throw new JSONException(bad.getMessage());}if(r.length()!=5||session==null||runs.put(id,r)!=null||!session.optString("source").equals("tracked")||!session.optString("health_connect","").isEmpty()||revision<0||!AwakeStore.STATES.contains(state)||error.length()>512||state.equals("off")&&p.enabled||state.equals("active")&&!session.isNull("end")||!p.enabled&&!Set.of("off","error").contains(state))throw new JSONException("Invalid awake run metadata");}
  Set<Long> ids=new HashSet<>();Map<Long,Integer> counts=new HashMap<>();for(int n=0;n<ee.length();n++){JSONObject e=ee.getJSONObject(n);long id=SensorProvenance.whole(e,"id"),sessionId=SensorProvenance.whole(e,"session"),from=SensorProvenance.whole(e,"start"),to=SensorProvenance.whole(e,"end"),ignored=SensorProvenance.whole(e,"ignored");String reason=SensorProvenance.text(e,"reason");JSONObject session=sessions.get(sessionId),run=runs.get(sessionId);if(e.length()!=6||id<=0||!ids.add(id)||session==null||run==null||!AwakeStore.REASONS.contains(reason)||from<session.getLong("start")||to<=from||to-session.getLong("start")>AwakeEngine.MAX||!session.isNull("end")&&to>session.getLong("end")||ignored<0||ignored>1||counts.merge(sessionId,1,Integer::sum)>10000)throw new JSONException("Invalid awake interval");AwakePolicy p=AwakePolicy.decode(run.getString("policy"));if(!p.enabled||run.getString("state").equals("off")||reason.equals("phone_use")&&!p.interaction||reason.equals("bright_light")&&!p.light||reason.equals("snooze")&&!p.snooze)throw new JSONException("Awake reason differs from frozen policy");}
 }
 static void restore(Store store,JSONObject root,Runnable guard)throws JSONException{for(String table:List.of("awake_runs","awake_estimates")){JSONArray rows=root.getJSONArray(table);for(int n=0;n<rows.length();n++){guard.run();JSONObject row=rows.getJSONObject(n);ContentValues v=new ContentValues();if(table.equals("awake_runs")){long id=row.getLong("session");v.put("session",id);v.put("policy",row.getString("policy"));String state=row.getString("state");v.put("state",state.equals("active")?"interrupted":state);v.put("error",row.getString("error"));v.put("revision",row.getLong("revision"));}else{for(String key:List.of("id","session","start","end","ignored"))v.put(key,row.getLong(key));v.put("reason",row.getString("reason"));}store.getWritableDatabase().insertOrThrow(table,null,v);}}}
}
